css:
.loader {
  position: relative;
  width: 48px;
  height: 48px;
}
.loader::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 2px;
  margin-top: -1px;
  background: #c7d2fe;
}
.loader::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 10px;
  height: 6px;
  margin: -3px 0 0 -5px;
  border: 2px solid #6366f1;
  border-radius: 50%;
  box-sizing: border-box;
  opacity: 0;
  animation: ripple 1.8s ease-out infinite;
}
.loader i {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 12px;
  height: 16px;
  margin: -16px 0 0 -6px;
  border-radius: 6px 6px 50% 50%;
  background: #6366f1;
  transform-origin: bottom center;
  animation: bob 1.8s ease-in-out infinite;
}
.loader i::before {
  content: "";
  position: absolute;
  top: -6px;
  left: 50%;
  width: 2px;
  height: 6px;
  margin-left: -1px;
  background: #4338ca;
}
.loader i::after {
  content: "";
  position: absolute;
  bottom: 2px;
  left: 0;
  right: 0;
  height: 4px;
  background: #eef2ff;
}
@keyframes bob {
  0%, 100% { transform: translateY(0); }
  45% { transform: translateY(-3px); }
  70% { transform: translateY(6px); }
}
@keyframes ripple {
  0%, 60% { opacity: 0; transform: scale(0.4); }
  70% { opacity: 0.7; transform: scale(1); }
  100% { opacity: 0; transform: scale(2.4); }
}
